script:
frappe.ui.form.on('User Authentication', {
    pin: function(frm) {
        let val = frm.doc.pin;
        if (val && val.toString().replace('-', '').length > 4) {
            frappe.msgprint("Value must not exceed 4 digits (max 9999)");
            frm.set_value('pin', '');
        }
    }
});

// Wait for the POS page controller to be instantiated
frappe.router.on('change', () => {
    if (frappe.get_route_str() === 'point-of-sale') {
        setup_pos_pin_override();
    }
});

// Run if directly loaded on point-of-sale
if (frappe.get_route_str() === 'point-of-sale') {
    $(document).ready(() => {
        setup_pos_pin_override();
    });
}

function setup_pos_pin_override() {
    // Retry until cur_pos controller is ready
    if (!window.cur_pos || !window.cur_pos.payment) {
        setTimeout(setup_pos_pin_override, 500);
        return;
    }

    // Intercept discount field change on POS cart
    let pos = window.cur_pos;

    // Prevent duplicate binding
    if (pos.__pin_override_attached) return;
    pos.__pin_override_attached = true;

    // Override the wrapper's discount input handler directly
    $(document).off('change', 'input[data-fieldname="discount_amount"], input[data-fieldname="additional_discount_percentage"]');
    $(document).on('change', 'input[data-fieldname="discount_amount"], input[data-fieldname="additional_discount_percentage"]', function(e) {
        let $input = $(this);
        let val = flt($input.val());

        if (val > 0 && !window.__pin_approved) {
            e.stopImmediatePropagation();
            e.preventDefault();

            // Revert value temporarily
            $input.val(0).trigger('input');

            // Launch PIN Dialog
            show_pin_dialog(
                function on_success() {
                    window.__pin_approved = true;
                    $input.val(val).trigger('input').trigger('change');
                    window.__pin_approved = false;
                },
                function on_cancel() {
                    $input.val(0).trigger('input');
                }
            );
        }
    });
}

function show_pin_dialog(on_success, on_cancel) {
    let d = new frappe.ui.Dialog({
        title: __('Authorization Required'),
        fields: [
            {
                label: __('Enter User PIN'),
                fieldname: 'pin',
                fieldtype: 'Password',
                reqd: 1
            }
        ],
        primary_action_label: __('Authorize'),
        primary_action(values) {
            frappe.call({
                method: 'validate_user_pin', // Must match API Method in Server Script
                args: {
                    pin: values.pin,
                    user: frappe.session.user
                },
                freeze: true,
                callback: function(r) {
                    if (r.message && r.message.status === 'success') {
                        d.hide();
                        frappe.show_alert({ message: __('Discount Approved'), indicator: 'green' }, 3);
                        if (on_success) on_success();
                    } else {
                        d.set_value('pin', '');
                        frappe.msgprint({
                            title: __('Access Denied'),
                            indicator: 'red',
                            message: r.message ? r.message.message : __('Invalid PIN')
                        });
                        if (on_cancel) on_cancel();
                    }
                }
            });
        }
    });

    d.show();
}

frappe.ui.form.on("Sales Invoice", {
    refresh(frm) {
        if (frm.doc.is_pos) {
            setup_discount_observer(frm);
        }
    }
});

function setup_discount_observer(frm) {
    inject_discount_inputs(frm);

    // Limit observation scope to POS form to save CPU performance
    const pos_container = document.querySelector(".pos-form") || document.body;
    const observer = new MutationObserver(frappe.utils.debounce(() => {
        let $target = $(".add-discount-field, .discount-field");
        if ($target.length && !$target.find("#custom_pos_discount_amt").length) {
            inject_discount_inputs(frm);
        }
    }, 200));

    observer.observe(pos_container, { childList: true, subtree: true });
}

function inject_discount_inputs(frm) {
    let $target = $(".add-discount-field");
    if (!$target.length) $target = $(".discount-field");
    if (!$target.length || $target.find("#custom_pos_discount_amt").length > 0) return;

    $target.css({ "padding": "0px", "border": "none" });

    $target.html(`
        <div class="custom-pos-discount-wrapper d-flex flex-column gap-2 my-2 w-100">
            <div class="form-group mb-1">
                <label class="small text-muted mb-1">Discount (%)</label>
                <input type="number" id="custom_pos_discount_pct" class="form-control input-xs" placeholder="0.00" value="${frm.doc.additional_discount_percentage || ''}" step="0.01" max="100">
            </div>
            <div class="form-group mb-0">
                <label class="small text-muted mb-1">Discount Amount</label>
                <input type="number" id="custom_pos_discount_amt" class="form-control input-xs" placeholder="0.00" value="${frm.doc.discount_amount || ''}" step="0.01">
            </div>
        </div>
    `);

    // Live Percentage Listener
    $(document).off("input change", "#custom_pos_discount_pct").on("input change", "#custom_pos_discount_pct", frappe.utils.debounce(function () {
        let pct = flt($(this).val());
        if (pct > 100) { pct = 100; $(this).val(100); }

        const active_frm = cur_frm || frm;
        const gross = get_gross_total(active_frm);
        const amt = flt((gross * pct) / 100, 2);

        $("#custom_pos_discount_amt").val(amt || "");
        apply_live_discount(active_frm, amt, pct);
    }, 200));

    // Live Amount Listener
    $(document).off("input change", "#custom_pos_discount_amt").on("input change", "#custom_pos_discount_amt", frappe.utils.debounce(function () {
        const amt = flt($(this).val(), 2);
        const active_frm = cur_frm || frm;
        const gross = get_gross_total(active_frm);
        const pct = gross > 0 ? flt((amt / gross) * 100, 2) : 0;

        $("#custom_pos_discount_pct").val(pct ? pct.toFixed(2) : "");
        apply_live_discount(active_frm, amt, pct);
    }, 200));
}

function get_gross_total(active_frm) {
    const items = active_frm.doc?.items || [];
    const total = items.reduce((acc, i) => acc + flt(i.amount || (i.rate * i.qty)), 0);
    return total > 0 ? total : 0;
}

function apply_live_discount(active_frm, amt, pct) {
    if (!active_frm || !active_frm.doc) return;

    frappe.run_serially([
        // 1. Set required target for ERPNext discount calculation
        () => active_frm.set_value("apply_discount_on", "Grand Total"),
        
        // 2. Pass values through set_value to notify form fields
        () => active_frm.set_value("additional_discount_percentage", flt(pct, 2)),
        () => active_frm.set_value("discount_amount", flt(amt, 2)),
        
        // 3. Trigger standard backend recalculation triggers
        () => {
            if (active_frm.cscript && active_frm.cscript.discount_amount) {
                active_frm.cscript.discount_amount(active_frm.doc);
            } else if (active_frm.script_manager) {
                active_frm.script_manager.trigger("discount_amount");
            }
        },
        
        // 4. Update UI displays and sync POS payment lines
        () => {
            const final_total = flt(active_frm.doc.grand_total || active_frm.doc.rounded_total);

            if (active_frm.doc.payments && active_frm.doc.payments.length > 0) {
                active_frm.doc.payments.forEach(p => {
                    p.amount = final_total;
                });
            }

            if (window.cur_pos) {
                if (window.cur_pos.cart && typeof window.cur_pos.cart.render_net_total === "function") {
                    window.cur_pos.cart.render_net_total();
                }
                if (window.cur_pos.payment && typeof window.cur_pos.payment.render_payment_section === "function") {
                    window.cur_pos.payment.render_payment_section();
                }
            }

            active_frm.refresh_fields([
                "grand_total",
                "net_total",
                "rounded_total",
                "paid_amount",
                "discount_amount",
                "additional_discount_percentage"
            ]);
        }
    ]);
}

frappe.ui.form.on("Sales Invoice", {
    refresh(frm) {
        if (frm.doc.is_pos) {
            setup_pin_protected_discount();
        }
    }
});

function setup_pin_protected_discount() {
    // Reset verification flag on initial view render
    localStorage.setItem("user_pin_verified", "0");

    // Intercept click on discount field wrapper using event capture
    $(document).off("click.pos_pin_check", ".add-discount-wrapper, .add-discount-field, .discount-field")
               .on("click.pos_pin_check", ".add-discount-wrapper, .add-discount-field, .discount-field", function (e) {
        
        const is_verified = localStorage.getItem("user_pin_verified");

        if (is_verified !== "1") {
            // Stop Frappe's default discount section rendering
            e.preventDefault();
            e.stopPropagation();
            e.stopImmediatePropagation();

            show_pos_pin_dialog();
            return false;
        }
    });
}

// Global Dialog Reference
let pos_pin_dialog = null;

function show_pos_pin_dialog() {
    // Clean up existing open dialogs or overlays
    if (pos_pin_dialog) {
        try { pos_pin_dialog.hide(); } catch (e) {}
        if (pos_pin_dialog.$wrapper) pos_pin_dialog.$wrapper.remove();
        pos_pin_dialog = null;
    }
    $(".modal-backdrop").remove();

    pos_pin_dialog = new frappe.ui.Dialog({
        title: __("Enter Security PIN"),
        fields: [
            {
                label: __("PIN"),
                fieldname: "pin",
                fieldtype: "Password",
                reqd: 1,
                description: __("Please enter your 4-digit PIN to apply discount")
            }
        ],
        primary_action_label: __("Verify"),
        primary_action(values) {
            frappe.call({
                method: "erpnext.accounts.doctype.user_authentication.user_authentication.validate_pin",
                args: {
                    user: frappe.session.user,
                    pin: values.pin
                },
                freeze: true,
                freeze_message: __("Verifying PIN..."),
                callback: function (r) {
                    if (r && r.message === true) {
                        frappe.show_alert({ message: __("PIN Verified"), indicator: "green" });
                        localStorage.setItem("user_pin_verified", "1");

                        // Close Dialog and cleanup layout
                        pos_pin_dialog.hide();
                        if (pos_pin_dialog.$wrapper) pos_pin_dialog.$wrapper.remove();
                        $(".modal-backdrop").remove();
                        $("body").removeClass("modal-open");

                        // Re-trigger standard POS discount input rendering
                        let $discount_target = $(".add-discount-wrapper, .add-discount-field, .discount-field").first();
                        if ($discount_target.length) {
                            $discount_target.trigger("click");
                        }
                    } else {
                        frappe.msgprint(__("Invalid PIN. Please try again."));
                        pos_pin_dialog.set_value("pin", "");
                    }
                }
            });
        }
    });

    pos_pin_dialog.no_cancel();
    pos_pin_dialog.show();
}
